final class PeerInfoHeaderNode: ASDisplayNode {
    // GlowGram mod: custom profile banner.
    private let exteraBannerNode = ASImageNode()
    private var exteraBannerFrame = CGRect.zero

    private func exteraUpdateProfileBanner(width: CGFloat, isSettings: Bool, transition: ContainedViewLayoutTransition) {
        guard isSettings, self.chatLocation.peerId == self.context.account.peerId else {
            if self.exteraBannerNode.supernode != nil {
                transition.updateAlpha(node: self.exteraBannerNode, alpha: 0.0, completion: { _ in
                    self.exteraBannerNode.removeFromSupernode()
                })
            }
            return
        }
        let store = ExteraPreferences.standard
        if let encoded = store.value(for: ExteraSettings.profileBanner),
           let data = Data(base64Encoded: encoded),
           let image = UIImage(data: data) {
            if self.exteraBannerNode.supernode == nil {
                self.exteraBannerNode.contentMode = .scaleAspectFill
                self.exteraBannerNode.clipsToBounds = true
                self.exteraBannerNode.cornerRadius = 18.0
                self.exteraBannerNode.isUserInteractionEnabled = false
                self.insertSubnode(self.exteraBannerNode, at: 0)
            }
            self.exteraBannerNode.image = image
            let bannerHeight = min(140.0, width * 0.45)
            let frame = CGRect(x: 0.0, y: -bannerHeight + 8.0, width: width, height: bannerHeight)
            if self.exteraBannerFrame != frame {
                self.exteraBannerFrame = frame
                transition.updateFrame(node: self.exteraBannerNode, frame: frame)
            }
        } else if self.exteraBannerNode.supernode != nil {
            transition.updateAlpha(node: self.exteraBannerNode, alpha: 0.0, completion: { _ in
                self.exteraBannerNode.removeFromSupernode()
            })
        }
    }
